Let $g(x) = \frac{f(x)}{f(x) + 1}$ for all real numbers $x$ where $f(x) \neq -1$. Which of the graphs below is the graph of $y = g(x)$? Assume $f$ is the function whose graph is shown above. 
(Note: The graph above means the original graph in the original problem.)

Your response should start after this graph.


[asy]
unitsize(0.5 cm);

picture[] graf;
int i, n;

real func(real x) {
  real y;
  if (x >= -3 && x <= 0) {y = -2 - x;}
  if (x >= 0 && x <= 2) {y = sqrt(4 - (x - 2)^2) - 2;}
  if (x >= 2 && x <= 3) {y = 2*(x - 2);}
  return(y);
}

real funcb(real x) {
  real y = min(-1,func(x))/(func(x) + 1);
  return(y);
}

real funcc(real x) {
  real y = func(x)/(func(x) + 1);
  return(y);
}

real funcd(real x) {
  real y = func(x)/(func(x) + 2);
  return(y);
}

real funce(real x) {
  real y = func(x)/(func(x) + 3);
  return(y);
}

real funcf(real x) {
  real y = func(x)/(func(x) - 1);
  return(y);
}

for (n = 1; n <= 5; ++n) {
  graf[n] = new picture;
  for (i = -5; i <= 5; ++i) {
    draw(graf[n],(i,-5)--(i,5),gray(0.7));
    draw(graf[n],(-5,i)--(5,i),gray(0.7));
  }
  draw(graf[n],(-5,0)--(5,0),Arrows(6));
  draw(graf[n],(0,-5)--(0,5),Arrows(6));

  label(graf[n],"$x$", (5,0), E);
  label(graf[n],"$y$", (0,5), N);
}

draw(graf[1],graph(funcb,-3,3),red);
draw(graf[2],graph(funcc,-3,3),red);
draw(graf[3],graph(funcd,-3,3),red);
draw(graf[4],graph(funce,-3,3),red);
draw(graf[5],graph(funcf,-3,3),red);

label(graf[1], "A", (0,-6));
label(graf[2], "B", (0,-6));
label(graf[3], "C", (0,-6));
label(graf[4], "D", (0,-6));
label(graf[5], "E", (0,-6));

add(graf[1]);
add(shift((12,0))*(graf[2]));
add(shift((24,0))*(graf[3]));
add(shift((6,-12))*(graf[4]));
add(shift((18,-12))*(graf[5]));
[/asy]
